export const BODY: string = "\n<p>إطار يغيّر كيف تبدو صورة: نفس الصورة في حد أبيض رفيع أو إطار Polaroid أو حد متدرج ساطع تشعر كثلاث صور مختلفة.</p>\n<p>اختيار نمط ليس زينة فقط: الإطار يحدد المزاج ويشير إلى السياق ويخبر المشاهد إن كانت الصورة ذكرى أو منتجًا أو عملًا فنيًا.</p>\n<p>يقارن هذا المقال أنماط الإطار الرئيسية وأين يعمل كل منها أفضل: يغطي وسائل التواصل الاجتماعي والطباعة وصور المنتج والصور الشخصية واختيارات اللون والظل التي تجعل إطارًا يشعر بالنية.</p>\n<h2 id=\"why-frames-matter\">لماذا تهم الإطارات</h2>\n<p>إطار يفصل الصورة عما حولها: في صفحة مليئة بأشياء أو خلاصة مزدحمة، صورة بحد تبرز، بينما صورة بلا حد قد تمتزج مع الخلفية.</p>\n<p>والإطارات تضيف أيضًا إحساسًا بالاكتمال: صورة بحد تشعر بالانتهاء، كطباعة رُكّبت، بينما صورة بلا حد قد تشعر كملف غير مكتمل. ونمط الإطار يخلق توقعات: إطار Polaroid يقول ذكرى عفوية، وإطار أسود رفيع يقول فنًا، وتوهج متدرج يقول تصميمًا رقميًا حديثًا.</p>\n<p>اختر الإطار حسب الرسالة لا حسب المظهر فقط: إطار يطابق السياق يقوي الصورة، بينما إطار يصارعه يضعف الصورة كلها.</p>\n<h2 id=\"minimal-frames\">إطارات أدنى: الأقل أكثر</h2>\n<p>إطار أدنى هو حد رفيع بلون واحد، غالبًا أبيض أو أسود، من 1 إلى 3 بالمئة من حجم الصورة: إنه النمط الأكثر تنوعًا، ويناسب تقريبًا أي صورة.</p>\n<p>الإطارات الأدنى تعمل لأنها لا تنافس الصورة: العين تلاحظ الصورة أولًا والإطار ثانيًا، وهو الترتيب الصحيح بالضبط. وتناسب أفضل للعمل الاحترافي: محافظ وقوائم منتجات وصور تحريرية، حيث الصورة يجب أن تتحدث وحدها دون زينة.</p>\n<p>أبقِ الإطارات الأدنى متسقة في مجموعة: سلسلة صور بنفس الحد الرفيع تبدو كمجموعة منسقة، بينما إطارات مختلطة تبدو عشوائية.</p>\n<h2 id=\"polaroid-and-retro\">إطارات Polaroid والرجعية</h2>\n<p>إطار Polaroid يحاكي الفيلم الفوري، بحد أبيض وشريط أسمك في الأسفل: يشعر بالحنين والعفوية والشخصية، ولهذا يناسب صور عطلات وذكريات.</p>\n<p>الشريط السفلي السميك هو توقيع النمط: يعطي مساحة لتعليق مكتوب بخط اليد أو تاريخ أو ملاحظة قصيرة، مثل طباعة Polaroid حقيقية. والإطارات الرجعية تعمل أفضل في صور عفوية وشخصية: تبدو خارج مكانها في صورة شخصية رسمية أو صورة منتج، حيث إطار أدنى نظيف أكثر ملاءمة.</p>\n<p>استخدم إطارات Polaroid باعتدال: خلاصة مليئة بها تشعر كمنتزه ترفيهي، بينما واحد أو اثنان بين صور نظيفة يشعران كذكرى عزيزة.</p>\n<h2 id=\"gallery-frames\">إطارات معرض: مظهر passepartout</h2>\n<p>إطار معرض هو حد أبيض واسع، غالبًا من 5 إلى 10 بالمئة، يحاكي طباعة بـpassepartout: يعطي الصورة مساحة للتنفس وإحساسًا رسميًا ومنسقًا.</p>\n<p>إطارات المعرض تناسب تصوير فن ومناظر وصورًا شخصية تستحق نظرة بطيئة: passepartout الواسع يجعل العين تتوقف ويدعو المشاهد لدراسة الصورة. وتعمل أفضل في مطبوعات ومحافظ: حد واسع في معاينة صغيرة لوسائل التواصل الاجتماعي يهدر مساحة، فاحتفظ بإطارات المعرض للشاشات الكبيرة والطباعة.</p>\n<p>اجمع إطار معرض مع خلفية بسيطة ومحايدة: يجب أن يكون passepartout الزينة الوحيدة، وأي شيء آخر ينافسه.</p>\n<h2 id=\"gradient-and-glow\">إطارات متدرجة وبتوهج</h2>\n<p>إطار بتوهج متدرج يمزج ألوانًا حول الصورة، خالقًا حدًا ناعمًا ومشرقًا: يشعر بالحداثة والرقمية، ويناسب رسومًا اجتماعية وملصقات وإعلانات أحداث.</p>\n<p>يُحسب التوهج من زاوية ومجموعة ألوان: تغيير الزاوية يحرك المزج حول الإطار، فالألوان نفسها قد تنتج مظاهر كثيرة مختلفة. والإطارات المتدرجة تعمل جيدًا في صور داكنة، حيث الحد الساطع يضيف طاقة: وقد تطغى على صورة فاتحة وجيدة التهوية، فاستخدمها عندما تحتاج الصورة دراما.</p>\n<p>أبقِ التوهج لطيفًا لعمل احترافي: تدرج ناعم يضيف صقلًا، بينما توهج قوي وساطع يشتت عن الصورة نفسها.</p>\n<h2 id=\"frames-for-social\">إطارات لوسائل التواصل الاجتماعي</h2>\n<p>خلاصات التواصل الاجتماعي مزدحمة، وإطار يساعد صورة على البروز: حد أبيض يفصل الصورة عن المنشورات حولها، وتتجه العين إلى الصورة المؤطرة.</p>\n<p>أبقِ إطارات التواصل الاجتماعي رفيعة: حد سميك يشغل مساحة في معاينة خلاصة صغيرة، تاركًا مكانًا أقل للصورة نفسها، وهي ما جاء الناس لرؤيته. واستخدم نمط إطار متسقًا عبر منشوراتك: حد مميز يصبح جزءًا من هويتك البصرية، ويبدأ المتابعون في اكتشاف منشوراتك قبل قراءة اسمك.</p>\n<p>جرّب الصورة المؤطرة بحجم الخلاصة: حد يبدو جيدًا بالحجم الكامل قد يهيمن على معاينة صغيرة، فراجع قبل النشر.</p>\n<h2 id=\"frames-for-print\">إطارات للطباعة</h2>\n<p>الصور المطبوعة استخدمت حدودًا لأكثر من قرن: حد أبيض حول طباعة يعطي إحساس معرض، ويعطي هامشًا للتعامل دون لمس الصورة.</p>\n<p>للمطبوعات، استخدم حدًا متوسطًا إلى واسع من 5 إلى 10 بالمئة: المساحة الإضافية تعطي الطباعة مكانًا للتنفس، وتناسب الطريقة الأبطأ والأكثر تعمدًا التي ينظر بها الناس إلى المطبوعات. وراجع حجم الطباعة قبل إضافة حد: حد يضيف إلى الأبعاد الكلية، فصورة ذات إطار تحتاج حجم ورق أكبر من نفس الصورة دونه.</p>\n<p>ولطباعة مؤطرة، الحد الرقمي جزء من التصميم: حد أبيض داخل إطار داكن يخلق تأثير passepartout، وهو العرض الكلاسيكي للمعرض.</p>\n<h2 id=\"frames-for-products\">إطارات لصور المنتج</h2>\n<p>صور المنتج تحتاج تأطيرًا متسقًا، لأن صفحة متجر بحدود غير متساوية تبدو مهملة: استخدم نفس نمط الإطار وحجمه لكل صورة منتج.</p>\n<p>حد أبيض رفيع يناسب معظم المنتجات: يفصل العنصر عن خلفية الصفحة دون تشتيت عن المنتج نفسه. وتجنب إطارات ملونة في صور المنتج إلا إذا كان اللون جزءًا من علامتك: إطار ساطع قد يتعارض مع المنتج ويجعل القائمة تبدو غير احترافية.</p>\n<p>ولعرض أو ترويج، قد يبرز إطار ملون العرض: حد أحمر أو ذهبي حول منتج مخفض يجذب الانتباه، وهو هدف الترويج.</p>\n<h2 id=\"frames-for-portraits\">إطارات للصور الشخصية</h2>\n<p>الصور الشخصية تناسب إطارات بسيطة: حد أبيض أو أسود رفيع يبقي التركيز على الوجه، بينما إطار لافت ينافس الشخص على الانتباه.</p>\n<p>تجنب حدودًا واسعة في صور شخصية: إطار كبير يجعل الوجه أصغر في الصورة العامة، ما يضعف الاتصال بين المشاهد والشخص. ولصورة شخصية رسمية، إطار أسود يضيف جدية: ولصورة شخصية عفوية، إطار أبيض يشعر بالخفة والود، ما يناسب صورًا عائلية وأسلوب حياة.</p>\n<p>أبقِ الإطار متسقًا في سلسلة صور شخصية: مجموعة صور رأس بإطارات متطابقة تبدو كمجموعة احترافية، بينما إطارات مختلطة تبدو عرضية.</p>\n<h2 id=\"frames-for-screenshots\">إطارات للقطات الشاشة</h2>\n<p>حد أبيض رفيع بظل ناعم يجعل لقطة شاشة تبدو كبطاقة: يفصل اللقطة عن الصفحة ويجعلها تبدو مصقولة.</p>\n<p>أبقِ الحد رفيعًا للقطات الشاشة: إطار سميك يشغل مساحة يحتاجها محتوى اللقطة، خاصة عندما يكون نص اللقطة صغيرًا. وصدّر لقطات مؤطرة كـPNG: الصيغة دون فقدان تحافظ على النص الصغير حادًا، ما يهم عندما يجب أن تُظهر اللقطة ضبطًا أو رسالة خطأ.</p>\n<p>واستخدم نفس نمط الإطار لكل لقطات دليل أو درس: الاتساق يساعد القارئ على اتباع الخطوات، بينما إطارات مختلطة تشتت عن التعليمات.</p>\n<h2 id=\"colour-theory\">نظرية اللون للإطارات</h2>\n<p>الأبيض هو أكثر لون إطار أمانًا: يناسب أي صورة ويعمل على أي خلفية ويعطي إحساس معرض نظيف لا يبدو قديمًا أبدًا.</p>\n<p>الأسود يضيف دراما وتركيزًا: يناسب صور مزاج داكن ولقطات ليلية وفنًا، حيث إطار فاتح سيبدو خارج مكانه. ومطابقة الإطار مع لون من الصورة تخلق مظهرًا مصممًا: إطار يأخذ لون فستان أو سماء أو منتج يربط الحد بالصورة.</p>\n<p>تجنب إطارات ساطعة ومشبعة في صور جدية: حد نيون في صورة زفاف يبدو كخطأ، بينما إطار محايد ناعم يبدو مقصودًا.</p>\n<h2 id=\"shadow-and-depth\">الظل والعمق</h2>\n<p>ظل منسدل يضيف عمقًا إلى صورة مؤطرة، جاعلًا إياها تبدو عائمة فوق الصفحة: يناسب بطاقات ولقطات شاشة ورسومًا اجتماعية.</p>\n<p>الظلال تعمل أفضل على خلفيات فاتحة، حيث الحد الداكن مرئي: على خلفية داكنة، يندمج الظل ويضيف قليلًا إلى الصورة. وللحفاظ على ظل، صدّر كـPNG أو WebP: JPG ليس له شفافية، فالظل يختفي في تصدير JPG وتبدو النتيجة مسطحة.</p>\n<p>ولتصميم أدنى ومسطح، احذف الظل تمامًا: إطار نظيف بلا عمق يناسب عملًا تحريريًا ومحافظ، حيث البساطة هي النقطة.</p>\n<h2 id=\"rounded-vs-square\">إطارات مدورة مقابل إطارات مربعة</h2>\n<p>الزوايا المربعة تشعر بالرسمية والدقة: تناسب صور منتج ووثائق وعملًا تحريريًا، حيث حد نظيف يطابق المحتوى.</p>\n<p>والزوايا المدورة تشعر بالود والحداثة: تناسب منشورات اجتماعية وبطاقات ورسوم تطبيقات، حيث حد ناعم يطابق الواجهة حولها. ونصف قطر الإطار يتحكم في المنحنى الخارجي ونصف قطر الصورة يتحكم في المنحنى الداخلي: تثبيت الاثنين على نفس القيمة يعطي إطارًا مدورًا موحدًا.</p>\n<p>ولنمط Polaroid، أبقِ الزوايا مربعة: المظهر الكلاسيكي للفيلم الفوري له زوايا حادة، وتدويرها أكثر مما يلزم يكسر الإحساس الرجعي.</p>\n<h2 id=\"mixing-frame-and-border\">كيف تمزج إطارات مع تعديلات أخرى</h2>\n<p>الإطار غالبًا الخطوة الأخيرة في تعديل لا الأولى: قص الصورة واضبط السطوع ثم أضف الحد، ليتطابق الإطار مع الصورة النهائية.</p>\n<p>اجمع إطارًا مع زوايا مدورة لمظهر بطاقة: حد رفيع بنصف قطر ناعم يشعر كبطاقة تطبيق حديثة، ما يناسب منشورات اجتماعية ورسومًا. واجمع إطارًا مع نص لملصق: صورة بحد وعنوان فوقها رسم كامل، جاهز للمشاركة دون مزيد من العمل.</p>\n<p>ولا تبالغ في المزج: إطار زائد مرشح قوي زائد نص جريء قد يطغى على الصورة، بينما اختيار قوي واحد في كل مرة يبقي التصميم نظيفًا.</p>\n<h2 id=\"trends-vs-timeless\">اتجاهات مقابل إطارات خالدة</h2>\n<p>أنماط الإطار تتبع اتجاهات مثل أي شيء آخر: توهجات متدرجة شائعة الآن، وإطارات Polaroid كانت شائعة قبل عقد، وحدود بيضاء أدنى لا تبدو قديمة أبدًا.</p>\n<p>لعمل يجب أن يدوم، اختر إطارًا خالدًا: حد أبيض أو أسود رفيع يبدو جيدًا بعد عشر سنوات كما اليوم، بينما توهج عصري قد يشعر بالقدم بسرعة. ولمنشورات اجتماعية تعيش يومًا، الاتجاهات جيدة: إطار متدرج يطابق الأسلوب الحالي قد يزيد التفاعل، وسيُنسى المنشور قبل أن يبدو الإطار قديمًا بكثير.</p>\n<p>وعند الشك، اختر أدنى: إطار بسيط لا يكون خطأ أبدًا، ويترك الصورة تحمل الصورة بدل الزينة.</p>\n<h2 id=\"choosing-cheat-sheet\">كيف تختار إطارًا: ورقة غش سريعة</h2>\n<p>استخدم حدًا أبيض رفيعًا لمنشورات اجتماعية وصور منتج وأي شيء يحتاج إطارًا نظيفًا وآمنًا: يعمل في كل مكان ولا يبدو سيئًا أبدًا.</p>\n<p>استخدم إطار Polaroid لذكريات عفوية وصور عطلات ومنشورات شخصية: يشعر بالحنين والمتعة، ما يناسب المحتوى. واستخدم حد معرض واسعًا لمطبوعات ومحافظ وتصوير فن: تأثير passepartout يعطي الصورة مساحة للتنفس وإحساسًا رسميًا.</p>\n<p>واستخدم توهجًا متدرجًا لملصقات ورسوم أحداث وإعلانات اجتماعية: الحد الساطع يضيف طاقة، ما يناسب محتوى مقصودًا لجذب الانتباه.</p>\n<h2 id=\"frames-for-events\">إطارات لإعلانات الأحداث</h2>\n<p>إعلانات الأحداث تحتاج إطارات تجذب الانتباه: توهج متدرج أو حد بلون جريء يجعل ملصقًا يبرز في خلاصة مليئة بصور بسيطة.</p>\n<p>طابق الإطار مع مزاج الحدث: تدرج ساطع يناسب حفلة أو حفلًا موسيقيًا، بينما حد أسود نظيف يناسب مؤتمرًا أو عشاءً رسميًا. وأبقِ تفاصيل الحدث مقروءة: إطار جريء لا يجب أن يغطي التاريخ أو المكان أو سعر التذكرة، فضع النص داخل الإطار جيدًا.</p>\n<p>واستخدم نفس نمط الإطار لكل منشورات حدث: مظهر متسق يساعد المتابعين على التعرف على الحدث عبر منشورات عدة، ما يبني توقعًا.</p>\n<p>للعملية خطوة بخطوة، راجع <a href=\"/ar/blog/kayfiyya-idafa-itar-ila-as-sura/\">كيف تضيف حدًا إلى صورة</a> والدليل الكامل في <a href=\"/ar/blog/dalil-munshi-itur-as-suwar/\">حدود للصور: دليل كامل</a>. ولتدوير زوايا صورة مؤطرة، جرّب أداة <a href=\"/ar/tadweer-zawaya-as-sura/\">تدوير زوايا الصورة</a>. وعندما تجد النمط الذي تبحث عنه، طبّقه مجانًا في المتصفح مع <a href=\"/ar/idafa-itar-ila-as-sura/\">مولد حدود الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"أي نمط إطار أفضل لمنشورات إنستغرام؟","answer":"حد أبيض رفيع هو الخيار الأكثر أمانًا: يفصل الصورة عن الخلاصة ويعمل في أي صورة ولا يبدو قديمًا أبدًا. وأبقه من 1 إلى 3 بالمئة لكي لا يشغل مساحة في معاينة صغيرة. واستخدم نفس النمط عبر منشوراتك لهوية مميزة."},{"question":"متى يجب أن أستخدم إطار Polaroid؟","answer":"لصور عفوية وشخصية مثل عطلات وحفلات وذكريات، حيث مظهر الفيلم الفوري الحنين يناسب المزاج: وتجنب إطارات Polaroid في صور شخصية رسمية أو صور منتج، حيث حد أدنى نظيف أكثر ملاءمة."},{"question":"هل إطارات التوهج المتدرج احترافية؟","answer":"قد تكون كذلك، عندما تُستخدم بلطف في المحتوى الصحيح: تدرج ناعم يناسب ملصقات ورسوم أحداث وإعلانات اجتماعية. ولمحافظ وعمل عملاء أو صور رسمية، حد أبيض أو أسود رفيع هو الخيار الأكثر أمانًا."},{"question":"أي نمط إطار يعمل أفضل لصور مطبوعة؟","answer":"حد أبيض واسع من 5 إلى 10 بالمئة، يحاكي طباعة معرض بـpassepartout ويعطي الصورة مساحة للتنفس: راجع حجم الورق أولًا، لأن الحد يضيف إلى الأبعاد الكلية."},{"question":"هل يجب أن تستخدم كل صور منتجي نفس الإطار؟","answer":"نعم، الاتساق في كتالوج يجعل المتجر يبدو مرتبًا وموثوقًا، بينما إطارات مختلطة تبدو عشوائية: استخدم نمط حد أبيض رفيع لكل صورة منتج، واحتفظ بإطار ملون للعروض فقط."},{"question":"هل الزوايا المدورة تناسب كل نمط إطار؟","answer":"لا، الزوايا المدورة تناسب منشورات اجتماعية وبطاقات ورسوم تطبيقات، حيث حد ناعم يطابق الواجهة: والزوايا المربعة تناسب صور منتج ووثائق وعملًا تحريريًا، حيث حد نظيف يطابق المحتوى."}];
